import{_ as t,a,o,a6 as i}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Get Admin Profile","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-get-profile","title":"Get Admin Profile","description":"Read the authenticated admin's profile. The token identifies the admin, so the query takes no arguments. This example selects every field the query returns.","query":"query readAdminProfile {\\n  readAdminProfile {\\n    id\\n    _id\\n    name\\n    email\\n    image\\n    status\\n    roleId\\n    roleName\\n    success\\n    message\\n  }\\n}\\n","variables":"{}\\n","response":"{\\n  \\"data\\": {\\n    \\"readAdminProfile\\": {\\n      \\"id\\": \\"/api/admin/admin_profiles/1\\",\\n      \\"_id\\": \\"1\\",\\n      \\"name\\": \\"Example Admin\\",\\n      \\"email\\": \\"admin@example.com\\",\\n      \\"image\\": null,\\n      \\"status\\": \\"1\\",\\n      \\"roleId\\": 1,\\n      \\"roleName\\": \\"Administrator\\",\\n      \\"success\\": true,\\n      \\"message\\": null\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/profile/get-profile.md","filePath":"api/graphql-api/admin/profile/get-profile.md","lastUpdated":1787725411000}`),n={name:"api/graphql-api/admin/profile/get-profile.md"};function d(r,e,s,l,h,c){return o(),a("div",null,e[0]||(e[0]=[i(`<h1 id="get-admin-profile" tabindex="-1">Get Admin Profile <a class="header-anchor" href="#get-admin-profile" aria-label="Permalink to &quot;Get Admin Profile&quot;">​</a></h1><p>Returns the profile of the admin who owns the Bearer token on the request. Use it to confirm a token is live and to learn who it belongs to — the account name and email to show in a header, and the role that governs everything else the token can do.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>readAdminProfile</code></td><td>Query</td><td>Return the authenticated admin&#39;s profile</td></tr></tbody></table><p>The query takes <strong>no arguments</strong>. The token alone selects the record, so there is no way to read another admin&#39;s profile here — use the <a href="/api/graphql-api/admin/settings/users/list.html">Settings → Users</a> queries for that.</p><h2 id="output-fields" tabindex="-1">Output Fields <a class="header-anchor" href="#output-fields" aria-label="Permalink to &quot;Output Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID!</td><td>Resource identifier in IRI form, <code>/api/admin/admin_profiles/&lt;id&gt;</code>.</td></tr><tr><td><code>_id</code></td><td>String</td><td>The numeric admin id, as a string.</td></tr><tr><td><code>name</code></td><td>String</td><td>Admin&#39;s display name.</td></tr><tr><td><code>email</code></td><td>String</td><td>Admin&#39;s login email.</td></tr><tr><td><code>image</code></td><td>String</td><td>Storage path of the avatar, or <code>null</code> when none is set.</td></tr><tr><td><code>status</code></td><td>String</td><td><code>&quot;1&quot;</code> when the account is active, <code>&quot;0&quot;</code> when disabled.</td></tr><tr><td><code>roleId</code></td><td>Int</td><td>Id of the assigned role, or <code>null</code> when the admin has no role.</td></tr><tr><td><code>roleName</code></td><td>String</td><td>Name of the assigned role, or <code>null</code> when the admin has no role.</td></tr><tr><td><code>success</code></td><td>Boolean</td><td>Always <code>true</code>. Present so the payload matches the REST response shape.</td></tr><tr><td><code>message</code></td><td>String</td><td>Always <code>null</code>. Present so the payload matches the REST response shape.</td></tr></tbody></table><p>Three of these behave differently from how they look:</p><ul><li><strong><code>status</code> is a string, not a boolean.</strong> Compare against <code>&quot;1&quot;</code> / <code>&quot;0&quot;</code>, or cast before testing — a bare truthiness check treats <code>&quot;0&quot;</code> as true in most languages.</li><li><strong><code>_id</code> is a string, not an integer</strong>, unlike <code>_id</code> on most other admin types. Cast it before using it as a numeric key.</li><li><strong><code>success</code> and <code>message</code> are constants</strong>, not a result signal. This query either resolves or fails at the transport; never branch on them.</li></ul><h2 id="role-fields" tabindex="-1">Role Fields <a class="header-anchor" href="#role-fields" aria-label="Permalink to &quot;Role Fields&quot;">​</a></h2><p><code>roleId</code> and <code>roleName</code> name the role, but they do not tell you what the token may do — a token can be narrowed below its owner&#39;s role. To gate UI, read <a href="/api/graphql-api/admin/navigation/permissions.html">Get Admin Permissions</a> instead, which returns the effective permission set after that narrowing.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>An unauthenticated request never reaches the GraphQL layer. A missing, malformed, expired, or revoked token is rejected by the transport with HTTP <code>401</code> and a plain JSON body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Unauthenticated.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;unauthenticated&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>No permission check applies — any valid token can read its own profile, whatever its permission mode.</p><h2 id="read-only" tabindex="-1">Read-Only <a class="header-anchor" href="#read-only" aria-label="Permalink to &quot;Read-Only&quot;">​</a></h2><p>There is no counterpart mutation. The admin API has no login, logout, forgot-password, or profile-update operation — accounts are managed in the admin panel, and tokens are issued from the Integration menu. To edit an admin record programmatically, use the <a href="/api/graphql-api/admin/settings/users/update.html">Settings → Users</a> mutations, which act on any admin by id and are permission-gated.</p>`,17)]))}const u=t(n,[["render",d]]);export{m as __pageData,u as default};
